cat > crates/editor-api/src/operations/classic_multicam_sources.rs <<'EOF'
//! Canonical microphone suggestions. Filename evidence is a hint, never identity.
use super::*;
use serde_json::{Map, Value};

#[derive(Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct Input {
    project_id: String,
    expected_revision: u64,
    #[schemars(length(min = 1, max = 32))]
    video_ids: Vec<String>,
}
#[derive(Serialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
struct Candidate {
    audio_id: String,
    score: u32,
    reason: String,
}
#[derive(Serialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
struct Suggestion {
    video_id: String,
    audio_id: Option<String>,
    candidates: Vec<Candidate>,
}
#[derive(Serialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
struct Output {
    revision: u64,
    has_external_audio: bool,
    suggestions: Vec<Suggestion>,
}
fn stem(name: &str) -> String {
    name.rsplit_once('.').map_or(name, |(base, _)| base).to_lowercase()
}
fn tokens(name: &str) -> Vec<String> {
    // Digits delimit recorder/camera prefixes (C7453lior, 0144_1lior).
    // Unicode alphabetic characters keep Hebrew names intact.
    stem(name).split(|c: char| !c.is_alphabetic())
        .filter(|s| s.chars().count() >= 3)
        .filter(|s| !["audio", "video", "camera", "mic", "microphone", "recording", "take", "wav", "mp4"].contains(s))
        .map(str::to_owned).collect()
}
fn score(video: &str, audio: &str) -> (u32, String) {
    let a = stem(video); let b = stem(audio);
    let compact = |s: &str| s.chars().filter(|c| c.is_alphanumeric()).collect::<String>();
    if !compact(&a).is_empty() && compact(&a) == compact(&b) {
        return (100, "Matching filename".into());
    }
    let shared: Vec<_> = tokens(video).into_iter().filter(|t| tokens(audio).contains(t)).collect();
    if !shared.is_empty() {
        return (80 + (shared.len().min(3) as u32 * 5), format!("Shared name: {}", shared.join(", ")));

